const { Client, GatewayIntentBits, PermissionsBitField } = require('discord.js');
const mongoose = require('mongoose');
const http = require('http');

// 1. Keeps the bot awake on Render
http.createServer((req, res) => {
  res.write('Bot is awake!');
    res.end();
    }).listen(3000);

    // 2. Cooldown Memory Systems
    const commandCooldowns = new Map();
    const dailyCooldowns = new Set();

    // 3. 💾 THE DATABASE SCHEMA
    const userSchema = new mongoose.Schema({
      userId: { type: String, required: true, unique: true },
        balance: { type: Number, default: 0 } 
        });
        const User = mongoose.model('User', userSchema);

        // Helper Function: Finds a user's account or creates a new one
        async function getUserData(id) {
          let user = await User.findOne({ userId: id });
            if (!user) {
                user = new User({ userId: id });
                    await user.save();
                      }
                        return user;
                        }

                        // 4. The Bot's Brain
                        const client = new Client({
                          intents: [
                              GatewayIntentBits.Guilds,
                                  GatewayIntentBits.GuildMessages,
                                      GatewayIntentBits.MessageContent 
                                        ]
                                        });

                                        // 5. Connect to Database
                                        client.once('ready', () => {
                                          console.log(`🤖 It's alive! Logged in as ${client.user.tag}`);
                                            mongoose.connect(process.env.MONGODB_URI)
                                                .then(() => console.log('✅ Connected to MongoDB Memory!'))
                                                    .catch((error) => console.log('❌ MongoDB Error:', error));
                                                    });

                                                    // 6. The Commands Section
                                                    client.on('messageCreate', async message => {
                                                      if (message.author.bot) return;

                                                        const msg = message.content.toLowerCase();
                                                          if (!msg.startsWith('cry!')) return;

                                                            const args = msg.split(' ');
                                                              const command = args[0]; 
                                                                const targetUser = message.mentions.users.first();
                                                                  const userId = message.author.id;

                                                                    // ==========================================
                                                                      // 🎁 24-HOUR COOLDOWN COMMAND
                                                                        // ==========================================
                                                                          if (command === 'cry!daily') {
                                                                              if (dailyCooldowns.has(userId)) {
                                                                                    return message.reply("⏳ You already claimed your daily reward! Come back in 24 hours.");
                                                                                        }
                                                                                            
                                                                                                const userData = await getUserData(userId);
                                                                                                    userData.balance += 1500;
                                                                                                        await userData.save();

                                                                                                            dailyCooldowns.add(userId);
                                                                                                                setTimeout(() => dailyCooldowns.delete(userId), 86400000); 

                                                                                                                    return message.reply(`🎁 **Daily Reward Claimed!**\n\nYou received:\n💎 +1,500 Crystals\n\nCurrent Balance: 💎 ${userData.balance}`);
                                                                                                                      }

                                                                                                                        // ==========================================
                                                                                                                          // ⏳ 3-MINUTE COOLDOWN SYSTEM
                                                                                                                            // ==========================================
                                                                                                                              const cdKey = `${userId}-${command}`;
                                                                                                                                
                                                                                                                                  if (commandCooldowns.has(cdKey)) {
                                                                                                                                      return message.reply(`⏳ Please wait 3 minutes before using the **${command}** command again!`);
                                                                                                                                        }
                                                                                                                                          
                                                                                                                                            commandCooldowns.set(cdKey, true);
                                                                                                                                              setTimeout(() => commandCooldowns.delete(cdKey), 180000);

                                                                                                                                                // ==========================================
                                                                                                                                                  // 💎 REAL ECONOMY COMMANDS
                                                                                                                                                    // ==========================================
                                                                                                                                                      if (command === 'cry!bal') {
                                                                                                                                                          const userData = await getUserData(userId);
                                                                                                                                                              return message.reply(`💎 **Crystal Balance**\n\n👤 User: <@${userId}>\n\n💰 Balance: ${userData.balance} Crystals`);
                                                                                                                                                                }
                                                                                                                                                                  
                                                                                                                                                                    else if (command === 'cry!work') {
                                                                                                                                                                        const jobs = ["Wizard Assistant", "Dragon Trainer", "Crystal Miner", "Royal Guard", "Potion Brewer"];
                                                                                                                                                                            const randomJob = jobs[Math.floor(Math.random() * jobs.length)];
                                                                                                                                                                                const randomPay = Math.floor(Math.random() * 1000) + 200;
                                                                                                                                                                                    
                                                                                                                                                                                        const userData = await getUserData(userId);
                                                                                                                                                                                            userData.balance += randomPay;
                                                                                                                                                                                                await userData.save();
                                                                                                                                                                                                    
                                                                                                                                                                                                        return message.reply(`⚒️ **${randomJob}**\n\nYou worked hard and earned:\n💎 +${randomPay} Crystals\n\nCurrent Balance: 💎 ${userData.balance}`);
                                                                                                                                                                                                          }

                                                                                                                                                                                                            else if (command === 'cry!pay') {
                                                                                                                                                                                                                if (!targetUser) return message.reply("Who are you paying? Example: `cry!pay @user 500`");
                                                                                                                                                                                                                    if (targetUser.id === userId) return message.reply("You can't pay yourself!");
                                                                                                                                                                                                                        
                                                                                                                                                                                                                            const amount = parseInt(args.find(arg => /^\d+$/.test(arg)));
                                                                                                                                                                                                                                if (!amount || amount <= 0) return message.reply("Please specify a valid amount to send! Example: `cry!pay @user 500`");

                                                                                                                                                                                                                                    const senderData = await getUserData(userId);
                                                                                                                                                                                                                                        if (senderData.balance < amount) return message.reply(`You don't have enough Crystals! Your balance is only 💎 ${senderData.balance}.`);

                                                                                                                                                                                                                                            const receiverData = await getUserData(targetUser.id);
                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                    senderData.balance -= amount;
                                                                                                                                                                                                                                                        receiverData.balance += amount;
                                                                                                                                                                                                                                                            await senderData.save();
                                                                                                                                                                                                                                                                await receiverData.save();

                                                                                                                                                                                                                                                                    return message.reply(`💸 **Payment Successful**\n\nYou sent 💎 ${amount} Crystals to <@${targetUser.id}>.\n\nYour New Balance: 💎 ${senderData.balance}`);
                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                        else if (command === 'cry!lb') {
                                                                                                                                                                                                                                                                            const topUsers = await User.find().sort({ balance: -1 }).limit(5);
                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                    if (topUsers.length === 0) return message.reply("The leaderboard is completely empty!");
                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                            let lbString = `🏆 **Crystal Leaderboard**\n\n`;
                                                                                                                                                                                                                                                                                                for (let i = 0; i < topUsers.length; i++) {
                                                                                                                                                                                                                                                                                                      lbString += `${i + 1}️⃣ <@${topUsers[i].userId}> — 💎 ${topUsers[i].balance}\n`;
                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                              return message.reply(lbString);
                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                  // ==========================================
                                                                                                                                                                                                                                                                                                                    // 🎲 REAL GAMBLING COMMANDS
                                                                                                                                                                                                                                                                                                                      // ==========================================
                                                                                                                                                                                                                                                                                                                        else if (command === 'cry!coinflip') {
                                                                                                                                                                                                                                                                                                                            const userData = await getUserData(userId);
                                                                                                                                                                                                                                                                                                                                if (userData.balance < 500) return message.reply("You need at least 500 Crystals to play coinflip!");

                                                                                                                                                                                                                                                                                                                                    const win = Math.random() < 0.5;
                                                                                                                                                                                                                                                                                                                                        if (win) {
                                                                                                                                                                                                                                                                                                                                              userData.balance += 500;
                                                                                                                                                                                                                                                                                                                                                    await userData.save();
                                                                                                                                                                                                                                                                                                                                                          return message.reply(`🪙 **Coin Flip**\n\nResult: **HEADS**\n\n🎉 You won! +500 Crystals\nNew Balance: 💎 ${userData.balance}`);
                                                                                                                                                                                                                                                                                                                                                              } else {
                                                                                                                                                                                                                                                                                                                                                                    userData.balance -= 500;
                                                                                                                                                                                                                                                                                                                                                                          await userData.save();
                                                                                                                                                                                                                                                                                                                                                                                return message.reply(`🪙 **Coin Flip**\n\nResult: **TAILS**\n\n😢 You lost! -500 Crystals\nNew Balance: 💎 ${userData.balance}`);
                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                        else if (command === 'cry!slots') {
                                                                                                                                                                                                                                                                                                                                                                                            const userData = await getUserData(userId);
                                                                                                                                                                                                                                                                                                                                                                                                if (userData.balance < 1000) return message.reply("You need at least 1,000 Crystals to play slots!");

                                                                                                                                                                                                                                                                                                                                                                                                    const win = Math.random() < 0.3; // 30% chance
                                                                                                                                                                                                                                                                                                                                                                                                        if (win) {
                                                                                                                                                                                                                                                                                                                                                                                                              userData.balance += 10000;
                                                                                                                                                                                                                                                                                                                                                                                                                    await userData.save();
                                                                                                                                                                                                                                                                                                                                                                                                                          return message.reply(`🎰 **Crystal Slots**\n\n🍇 🍇 🍇\n\nJACKPOT!\n\n💎 +500 Crystals\nNew Balance: 💎 ${userData.balance}`);
                                                                                                                                                                                                                                                                                                                                                                                                                              } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                    userData.balance -= 1000;
                                                                                                                                                                                                                                                                                                                                                                                                                                          await userData.save();
                                                                                                                                                                                                                                                                                                                                                                                                                                                return message.reply(`🎰 **Crystal Slots**\n\n🍋 🍒 🍇\n\nYou Lost!\n\n💎 -200 Crystals\nNew Balance: 💎 ${userData.balance}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                          // 🦹 CRIME COMMANDS
                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                              else if (command === 'cry!beg') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const begAmount = Math.floor(Math.random() * 150) + 10;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const userData = await getUserData(userId);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          userData.balance += begAmount;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              await userData.save();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return message.reply(`🥺 You begged around town.\n\nA kind traveler gave you\n💎 +${begAmount} Crystals`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ❤️ MARRIAGE COMMANDS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            else if (command === 'cry!marry') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!targetUser) return message.reply("You need to tag someone to propose! Example: `cry!marry @user`");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return message.reply(`💍 **Marriage Proposal**\n\n<@${targetUser.id}>\n\nDo you accept? (Reply with \`cry!accept\` or \`cry!decline\`)`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else if (command === 'cry!accept') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return message.reply(`🎉 **Congratulations!**\n\nYou are now happily married! ❤️`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                else if (command === 'cry!decline') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return message.reply(`💔 **Proposal Declined**\n\nBetter luck next time...`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else if (command === 'cry!partner') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return message.reply(`❤️ **Partner**\n\nYou are happily married!`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                else if (command === 'cry!divorce') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return message.reply(`💔 **Divorce Complete**\n\nYou are now single again.`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // 🎉 FUN COMMANDS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              else if (command === 'cry!crystalfortune') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const fortunes = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "The stars whisper... Today is your lucky day. ✨",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "Beware! The crystal mines are dangerous today. ⚠️",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "I sense great wealth in your future! 💰"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return message.reply(`🔮 **Crystal Fortune**\n\n"${fortunes[Math.floor(Math.random() * fortunes.length)]}"`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                else if (command === 'cry!tea') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const teaSpills = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          "Someone secretly has a crush on you... 👀",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "I heard someone is going bankrupt from playing slots... 🎰",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      "Wait, didn't someone just get robbed yesterday? 🚔"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return message.reply(`☕ **Crystal Tea**\n\n${teaSpills[Math.floor(Math.random() * teaSpills.length)]}`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  else if (command === 'cry!gay') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!targetUser) return message.reply("Tag someone to check their meter! Example: `cry!gay @user`");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const percent = Math.floor(Math.random() * 101);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return message.reply(`🌈 **Gay Meter**\n\n<@${targetUser.id}> is ${percent}% Gay!`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 🤝 SOCIAL COMMANDS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else if (command === 'cry!hug') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!targetUser) return message.reply("Tag someone to hug! Example: `cry!hug @user`");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return message.reply(`🤗 <@${userId}> hugged <@${targetUser.id}>! How wholesome! 💜\nhttps://media.giphy.com/media/od5H3PmEG5EVq/giphy.gif`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    else if (command === 'cry!slap') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!targetUser) return message.reply("Tag someone to slap! Example: `cry!slap @user`");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return message.reply(`👋 Ouch! <@${userId}> slapped <@${targetUser.id}>!\nhttps://media.giphy.com/media/Zau0yrl17uzdK/giphy.gif`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                else if (command === 'cry!blush') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return message.reply(`😊 <@${userId}> is blushing...\nhttps://media.giphy.com/media/13cptIwW9bgzk6UVyx/giphy.gif`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // 🛡 ADMIN COMMANDS (Protected!)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              else if (command === 'cry!addmoney') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // SECURITY CHECK: Requires Administrator Permission!
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (!message.member.permissions.has(PermissionsBitField.Flags.Administrator)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return message.reply("❌ **Access Denied!** Only server admins can use this command.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!targetUser) return message.reply("Tag someone to add money to! Example: `cry!addmoney @user 5000`");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const amount = parseInt(args.find(arg => /^\d+$/.test(arg)));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!amount) return message.reply("Please provide an amount!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const userData = await getUserData(targetUser.id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            userData.balance += amount;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                await userData.save();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return message.reply(`✅ **Success**\n\nAdded 💎 ${amount} Crystals to <@${targetUser.id}>.`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          else if (command === 'cry!removemoney') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // SECURITY CHECK: Requires Administrator Permission!
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (!message.member.permissions.has(PermissionsBitField.Flags.Administrator)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return message.reply("❌ **Access Denied!** Only server admins can use this command.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!targetUser) return message.reply("Tag someone to remove money from! Example: `cry!removemoney @user 5000`");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const amount = parseInt(args.find(arg => /^\d+$/.test(arg)));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!amount) return message.reply("Please provide an amount!");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const userData = await getUserData(targetUser.id);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    userData.balance -= amount;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        await userData.save();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return message.reply(`✅ **Success**\n\nRemoved 💎 ${amount} Crystals from <@${targetUser.id}>.`);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // 📚 UTILITY COMMAND
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ==========================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      else if (command === 'cry!help') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return message.reply(`✨ **Crystal Bot Help Menu** ✨\n\n💎 **Economy:** \`cry!bal\`, \`cry!work\`, \`cry!daily\`, \`cry!pay\`, \`cry!lb\`\n🎲 **Gambling:** \`cry!coinflip\`, \`cry!slots\`\n🦹 **Crime:** \`cry!beg\`\n❤️ **Marriage:** \`cry!marry\`, \`cry!accept\`, \`cry!decline\`, \`cry!partner\`, \`cry!divorce\`\n🎉 **Fun:** \`cry!crystalfortune\`, \`cry!gay\`, \`cry!tea\`\n🤝 **Social:** \`cry!hug\`, \`cry!slap\`, \`cry!blush\`\n🛡 **Admin:** \`cry!addmoney\`, \`cry!removemoney\``);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Remove cooldown if they mistyped a command
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    commandCooldowns.delete(cdKey);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }); 

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // 7. Turn the bot on!
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      client.login(process.env.TOKEN);




                                            